declare(strict_types=1);

/**
 * lote23.php — Liquidaciones al transportista.
 *
 * REQUIERE el lote 22 aplicado. (El 21 sigue pendiente en tu carpeta, pero es
 * independiente de esto: toca otros ficheros y puede ir antes o después.)
 *
 * La otra cara de la factura: lo que se le PAGA al transportista por sus cargas,
 * menos la tarifa de despacho que se le cobra, menos sus descuentos, más lo que
 * se le reembolsa.
 *
 * LO QUE HACE QUE LAS DOS CARAS CUADREN
 *
 * Si la carga ya se facturó, la liquidación NO vuelve a calcular: reutiliza la
 * MISMA instantánea congelada que usó la factura. Si cada una calculara la suya,
 * entre marzo y abril podría aprobarse un gasto y la tarifa descontada dejaría
 * de coincidir con la facturada. La diferencia sería pequeña y constante — la
 * peor clase de error, porque nadie la ve hasta que alguien cuadra un trimestre.
 *
 * Para eso hace falta saber qué instantánea usó cada línea de factura, y esa
 * columna faltaba: `carrier_settlement_lines.financial_snapshot_id` ya estaba en
 * el esquema, pero `invoice_line_items` no la tenía. La migración la añade — es
 * un hueco del lote 22 que no vi hasta llegar aquí.
 *
 * Qué instala:
 *   • Migración reanudable: la serie de numeración de liquidaciones en
 *     `tenant_settings` y el enlace a la instantánea en las líneas de factura.
 *   • `SnapshotStore`, que ahora comparten factura y liquidación.
 *   • `SettlementBuilder` y `SettlementController`: listado, alta en dos pasos,
 *     ficha, entrega, pago y anulación.
 *   • Tres pantallas y su diccionario EN/ES.
 *   • 10 pruebas Pest, incluida la que comprueba que las dos caras usan la misma
 *     instantánea y que solo se congela UNA.
 *
 * FACTORING: si el transportista tiene una asignación viva, la liquidación lo
 * anota para que quien pague sepa a quién. La plataforma REGISTRA; no mueve
 * dinero.
 *
 * El DDL se ejecutó contra un MySQL 8.0.46 real con tu esquema entero cargado:
 * desde cero, sobre lo ya aplicado, y desde un estado a medias.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote23.php            # aplica
 *     php lote23.php --dry-run  # dice qué haría y no toca nada
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);
$hechos = []; $saltados = []; $errores = [];

function ruta(string $rel): string { global $raiz; return $raiz.DIRECTORY_SEPARATOR.$rel; }

function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (is_file($destino) && file_get_contents($destino) === $contenido) { $saltados[] = "= {$rel}"; return; }
    $existia = is_file($destino);
    if ($dry) { $hechos[] = ($existia ? '~ ' : '+ ').$rel; return; }
    $dir = dirname($destino);
    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) { $errores[] = "no se pudo crear el directorio {$dir}"; return; }
    if (file_put_contents($destino, $contenido) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados. Si el resultado ya está, se salta; si el texto de
 * partida está una sola vez, se sustituye; si no, se aborta el fichero entero
 * sin escribir — un anclaje que no encaja significa que el fichero no es el que
 * este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (! is_file($destino)) { $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?"; return; }
    $texto = file_get_contents($destino); $aplicados = 0; $yaEstaban = 0;
    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) { $yaEstaban++; continue; }
        $veces = substr_count($texto, $antes);
        if ($veces !== 1) { $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero."; return; }
        $texto = str_replace($antes, $despues, $texto); $aplicados++;
    }
    if ($aplicados === 0) { $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)"; return; }
    if ($dry) { $hechos[] = "~ {$rel} ({$aplicados} trozo(s))"; return; }
    if (file_put_contents($destino, $texto) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

