/* ── Ficheros que se modifican ───────────────────────────────────────── */

editar("app/Support/Finance/InvoiceBuilder.php", [
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('ICAgICAgICBEQjo6dGFibGUoJ2ludm9pY2VfbGluZV9pdGVtcycpLT5pbnNlcnQoJGxpbmVhcyk7CgogICAgICAgIHJldHVybiAkaW52b2ljZUlkOwogICAgfQp9Cg==')],
]);

editar("routes/auth.php", [
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
]);

