/* ── Parte ───────────────────────────────────────────────────────────────── */

echo $dry ? "SIMULACIÓN (no se escribió nada)\n\n" : "lote23 — liquidaciones al transportista\n\n";
foreach ($hechos as $l) { echo "  {$l}\n"; }
if ($saltados !== []) { echo "\n  ya estaba:\n"; foreach ($saltados as $l) { echo "    {$l}\n"; } }
if ($errores !== []) {
    echo "\nERRORES:\n";
    foreach ($errores as $l) { echo "  ! {$l}\n"; }
    echo "\nNada de lo que falló se escribió a medias.\n";
    exit(1);
}
if (! $dry) { echo <<<'TXT'

Siguiente paso, en este orden:

  php artisan migrate
  npm run build
  ./vendor/bin/pest

TXT; }
exit(0);
